const body = $('Check webhook').first().json.body;
const schema = $json;
let items = body.items;
if (typeof body.csv === 'string') {
  const [head, ...lines] = body.csv.trim().split(/\r?\n/);
  const cols = head.split(',').map((c) => c.trim());
  items = lines.map((line) => Object.fromEntries(line.split(',').map((v, i) => [cols[i], v.trim()])));
}
const isDate = (v) => { if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return false; const d = new Date(v + 'T00:00:00Z'); return !isNaN(d) && d.toISOString().slice(0, 10) === v; };
const seen = new Set();
const rows = (Array.isArray(items) ? items : []).map((r, index) => {
  const errors = [];
  for (const [name, f] of Object.entries(schema.fields)) {
    const v = r?.[name];
    const empty = v === undefined || v === null || (typeof v === 'string' && v.trim() === '') || (Array.isArray(v) && v.length === 0);
    if (empty) { if (f.required) errors.push(`missing:${name}`); continue; }
    const s = String(v);
    if (f.type === 'string') { if (f.max && s.length > f.max) errors.push(`too_long:${name}`); if (f.min && s.length < f.min) errors.push(`too_short:${name}`); }
    if (f.type === 'enum' && !f.values.includes(s)) errors.push(`not_allowed:${name}`);
    if (f.type === 'email' && !/^[\w.+-]+@[\w-]+(\.[\w-]+)+$/.test(s)) errors.push(`bad_format:${name}`);
    if (f.type === 'phone' && !/^0\d{1,2}-\d{3,4}-\d{4}$/.test(s)) errors.push(`bad_format:${name}`);
    if (f.type === 'date' && !isDate(s)) errors.push(`bad_format:${name}`);
    if (f.type === 'pattern' && !new RegExp(f.pattern).test(s)) errors.push(`bad_format:${name}`);
    if (f.type === 'list') { if (!Array.isArray(v)) errors.push(`bad_format:${name}`); else { if (f.min_items && v.length < f.min_items) errors.push(`too_few:${name}`); if (f.max_items && v.length > f.max_items) errors.push(`too_many:${name}`); } }
  }
  const key = String(r?.[schema.key] ?? '');
  if (key && seen.has(key)) errors.push('duplicate_in_batch');
  if (key) seen.add(key);
  return { row: index + 1, key, ok: errors.length === 0, errors };
});
const codes = {};
for (const row of rows) for (const e of row.errors) codes[e] = (codes[e] ?? 0) + 1;
const valid = rows.filter((r) => r.ok).length;
return [{ json: { schema: schema.name, batch: body.batch ?? '', total: rows.length, valid, invalid: rows.length - valid, rows, codes } }];
